<script setup lang="ts">definePageMeta({layout:'app'});const report=ref<any>(null);const {error}=useApiError();onMounted(async()=>{try{report.value=await api('/reports')}catch(e:any){error.value=e.message}})</script>
<template><div class="workhead"><div><p class="eyebrow">INSIGHT</p><h1>服務報表</h1><p class="muted">依登入者權限顯示個人或全體彙總。</p></div></div><div v-if="report" class="grid cards"><article v-for="(v,k) in report.summary||report" :key="k" class="card"><span class="eyebrow">{{k}}</span><h2>{{typeof v==='object'?'—':v}}</h2></article></div><div v-if="report?.teachers" class="tablewrap" style="margin-top:20px"><table class="table"><thead><tr><th>同工</th><th>服務場次</th><th>出席</th></tr></thead><tbody><tr v-for="r in report.teachers" :key="r.id"><td>{{r.name}}</td><td>{{r.sessions}}</td><td>{{r.attendance}}</td></tr></tbody></table></div><p v-if="error" class="error">{{error}}</p></template>
